import crypto from "crypto";
function hashPassword(password) {
  const salt = crypto.randomBytes(16).toString("hex");
  const hash = crypto.scryptSync(password, salt, 64).toString("hex");
  return { salt, hash };
}
function verifyPassword(password, salt, storedHash) {
  const hash = crypto.scryptSync(password, salt, 64).toString("hex");
  return crypto.timingSafeEqual(Buffer.from(hash, "hex"), Buffer.from(storedHash, "hex"));
}
function generateNumericOTP() {
  const num = crypto.randomInt(1e5, 999999);
  return num.toString();
}
function hashOTP(otp) {
  return crypto.createHash("sha256").update(otp).digest("hex");
}
function verifyOTP(enteredOtp, storedHash) {
  const enteredHash = hashOTP(enteredOtp);
  return crypto.timingSafeEqual(Buffer.from(enteredHash, "hex"), Buffer.from(storedHash, "hex"));
}
var DEFAULT_RECOVERY_KEY = "Devaraj@Recovery#2026";
function getAdminRecoveryKey() {
  return process.env.ADMIN_RECOVERY_KEY || DEFAULT_RECOVERY_KEY;
}
function verifyRecoveryKey(entered) {
  const expected = getAdminRecoveryKey();
  const a = Buffer.from((entered || "").toString().trim());
  const b = Buffer.from(expected);
  if (a.length !== b.length) return false;
  return crypto.timingSafeEqual(a, b);
}
var SECRET = process.env.SESSION_SECRET || "devaraj-crackers-super-secret-key-2026";
function createSessionToken(user) {
  const payload = {
    id: user.id,
    username: user.username,
    role: user.role,
    name: user.name,
    timestamp: Date.now()
  };
  const str = Buffer.from(JSON.stringify(payload)).toString("base64");
  const sig = crypto.createHmac("sha256", SECRET).update(str).digest("hex");
  return `${str}.${sig}`;
}
function verifySessionToken(token) {
  if (!token || !token.includes(".")) return null;
  const [str, sig] = token.split(".");
  const expectedSig = crypto.createHmac("sha256", SECRET).update(str).digest("hex");
  if (sig !== expectedSig) return null;
  try {
    const payload = JSON.parse(Buffer.from(str, "base64").toString("utf-8"));
    if (Date.now() - payload.timestamp > 7 * 24 * 60 * 60 * 1e3) {
      return null;
    }
    return payload;
  } catch {
    return null;
  }
}

// server/kv.ts
function getKvUrl() {
  return process.env.KV_REST_API_URL || process.env.UPSTASH_REDIS_REST_URL || null;
}
function getKvToken() {
  return process.env.KV_REST_API_TOKEN || process.env.UPSTASH_REDIS_REST_TOKEN || null;
}
function isKvConfigured() {
  return !!(getKvUrl() && getKvToken());
}
async function kvGet(key) {
  const url = getKvUrl();
  const token = getKvToken();
  if (!url || !token) return null;
  try {
    const res = await fetch(`${url}/get/${encodeURIComponent(key)}`, {
      headers: { Authorization: `Bearer ${token}` }
    });
    if (!res.ok) return null;
    const data = await res.json().catch(() => null);
    return data && typeof data.result === "string" ? data.result : null;
  } catch (err) {
    console.error("KV get error:", err);
    return null;
  }
}
async function kvSet(key, value) {
  const url = getKvUrl();
  const token = getKvToken();
  if (!url || !token) return false;
  try {
    const res = await fetch(`${url}/set/${encodeURIComponent(key)}`, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${token}`,
        "Content-Type": "text/plain"
      },
      body: value
    });
    return res.ok;
  } catch (err) {
    console.error("KV set error:", err);
    return false;
  }
}

